import { Request } from "../../request";
import { SinglePayload, DataRecordsQueryResult } from "../../types/payload";
import { Payload } from "../../types/payload";
import { Params } from "../../types/params";
/**
 * Data Tables admin methods. Wraps the `/v2/data-tables` API:
 * list/get tables and create/get/query/update/delete records.
 *
 * Responses are returned as the API sends them (wrapped in `{ data: ... }`),
 * consistent with the member methods.
 */
export default class DataTablesMethods extends Request {
    private endpoint;
    constructor(secretKey: string, test?: boolean, baseUrl?: string);
    /** List all data tables (and their field definitions) for the app. */
    list(): Promise<SinglePayload<{
        tables: Payload.Transforms["DataTable"][];
    }>>;
    /** Get a single data table by key (or id) including its fields. */
    get(params: Params.GetDataTable): Promise<SinglePayload<Payload.Transforms["DataTable"]>>;
    /** Create a record in a table. */
    createRecord(params: Params.CreateDataRecord): Promise<SinglePayload<Payload.Transforms["DataRecord"]>>;
    /**
     * Get a single record by id (convenience wrapper over a findUnique query).
     * Resolves to `{ data: { record } }`; rejects with "Record not found" (404)
     * if the id doesn't exist.
     */
    getRecord(params: Params.GetDataRecord): Promise<SinglePayload<{
        record: Payload.Transforms["DataRecord"];
    }>>;
    /**
     * Query records with the Prisma-like findMany/findUnique surface.
     * Resolves to `{ data: { records, pagination } }`, `{ data: { record } }`,
     * or `{ data: { _count } }` depending on the query.
     */
    queryRecords(params: Params.QueryDataRecords): Promise<SinglePayload<DataRecordsQueryResult>>;
    /** Update a record (partial — only the provided fields change). */
    updateRecord(params: Params.UpdateDataRecord): Promise<SinglePayload<Payload.Transforms["DataRecord"]>>;
    /** Delete a record. Resolves to the deleted record. */
    deleteRecord(params: Params.DeleteDataRecord): Promise<SinglePayload<Payload.Transforms["DataRecord"]>>;
}
